options.helpers:
const hb = context.handlebars;
// os frames vivem em context.panelData.series (NAO em context.data — esse e so o frame
// selecionado, achatado em linhas). Descoberto por painel de debug.
const S = (context.panelData && context.panelData.series) || (context.data && context.data.series) || [];
const val = n => { for (const fr of S) { const f = (fr.fields || []).find(x => x.name === n);
  if (f && f.values) { const v = f.values.get ? f.values.get(0) : f.values[0];
    if (v !== null && v !== undefined) return v; } } return null; };
const num = n => { const v = val(n); return v === null ? 0 : Number(v); };
const som = ks => ks.reduce((a, k) => a + num(k), 0);
const G = {
  ne_sol: num('ne_solar'), ne_eol: num('ne_eolica'), ne_tot: num('ne_total'), ne_carga: num('ne_carga'),
  br_sol: som(['n_solar','ne_solar','se_solar','s_solar']),
  br_eol: som(['n_eolica','ne_eolica','se_eolica','s_eolica']),
  br_tot: som(['n_total','ne_total','se_total','s_total']),
  nossa: num('nossa_mw'), quando: val('quando'), quando_w2: val('quando_w2')
};
const gw = v => (v / 1000).toFixed(2);
const pc = (a, b) => b > 0 ? (100 * a / b).toFixed(2) : '--';
const fx = (a, b) => b > 0 ? (100 * a / b).toFixed(1) : '0';
hb.registerHelper('g', k => G[k] === undefined ? '?' : (typeof G[k] === 'number' ? gw(G[k]) : G[k]));
hb.registerHelper('mw', () => G.nossa.toFixed(2));
hb.registerHelper('pct', k => pc(G.nossa, G[k]));
hb.registerHelper('fatia', k => fx(G[k], G[k.slice(0,2) + '_tot']));  // % da fonte na geracao da regiao
hb.registerHelper('hora', () => {
  const s = String(G.quando || ''); const m = s.match(/T(\d{2}:\d{2})/);
  const d = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  return (d ? d[3] + '/' + d[2] + '/' + d[1] : '') + (m ? ' ' + m[1] : '');
});
// ---- IDADE DO DADO DA WAY2 (acrescentado 27/07/2026) ----
// O "agora" de referencia e o Data do ONS, nao o relogio do navegador: o ONS tem ~1 min de idade e
// vem com fuso, entao a conta nao depende do computador de quem olha estar certo.
const hhmm = s => { const m = String(s || '').match(/T(\d{2}):(\d{2})/); return m ? [+m[1], +m[2]] : null; };
const idadeMin = () => { const a = hhmm(G.quando), b = hhmm(G.quando_w2);
  if (!a || !b) return null;
  let d = (a[0] * 60 + a[1]) - (b[0] * 60 + b[1]);
  if (d < -720) d += 1440; if (d > 720) d -= 1440;   // virada da meia-noite
  return d; };
// LIMIARES MEDIDOS em 27/07/2026, nao estimados. Total (ONS - slot da Way2) observado: 13 min as
// 11:33 e 22 min as 16:48. A decomposicao das 16:48 mostra que 20 dos 22 min sao atraso de
// PUBLICACAO da propria Way2 (o nosso fluxo tinha 3 min). Entao 13-22 min E o normal.
const OK = 25, ATENCAO = 40;   // 40 min = oito slots de 5 perdidos: nao e variacao, e coisa parada
hb.registerHelper('hw2', () => { const b = hhmm(G.quando_w2); return b
  ? String(b[0]).padStart(2, '0') + ':' + String(b[1]).padStart(2, '0') : '--:--'; });
hb.registerHelper('idade', () => { const d = idadeMin();
  if (d === null) return 'sem leitura';
  if (d < 0) return 'adiantado ' + (-d) + ' min';     // relogio de alguma ponta fora de hora
  if (d <= OK) return 'h\u00e1 ' + d + ' min';
  if (d <= ATENCAO) return 'atraso ' + d + ' min';
  return 'sem atualizar h\u00e1 ' + d + ' min'; });
const nivel = () => { const d = idadeMin();
  if (d === null || d < 0 || d > ATENCAO) return 2;   // falha
  return d > OK ? 1 : 0; };                            // atencao : normal
hb.registerHelper('cor_idade', () => ['#A8B0BC', '#F5A623', '#C85C60'][nivel()]);
hb.registerHelper('cor_ponto', () => ['#F5A623', '#F5A623', '#C85C60'][nivel()]);
